// Pure text generation for the Lua file vtnc writes under
// ~/.config/hypr/vtnc (0.507, decisions 7.2/7.3/7.4). No I/O here —
// cli/lib/hyprland-write.js does the actual write plus `hyprctl reload`,
// triggered from the running shell by core/HyprlandSync.qml. Kept separate
// from config-shape.mjs because this is about Hyprland's own Lua syntax,
// not vtnc's config document shape.

const WARNING_BANNER = [
    "-- GENERATED BY vtnc. DO NOT EDIT BY HAND.",
    "-- Regenerated whole every time a keybind changes (decision 7.2) --",
    "-- anything written here by hand is lost on the next change. Edit",
    "-- keybinds from vtnc's Settings > Keybinds page, or with",
    "-- `vtnc hyprland set keybinds '<json>'`.",
].join("\n");

// Every key vtnc has ever known about for this config, enabled or not.
// Unbound first, always, so: (a) turning a keybind off actually drops it
// from `hyprctl binds -j` instead of leaving a stale bind from the last
// reload that did include it, and (b) a key reused from a previous version
// of this same file never ends up bound twice. Decision 7.4 is the reason
// this stays scoped to exactly these keys and nothing else — a user's own
// bind, declared anywhere outside vtnc's folder, is never named here, so
// it's never touched.
export function managedKeys(hyprland) {
    const seen = new Set();
    const keys = [];
    for (const keybind of hyprland.keybinds ?? []) {
        if (!seen.has(keybind.key)) {
            seen.add(keybind.key);
            keys.push(keybind.key);
        }
    }
    return keys;
}

export function enabledKeybinds(hyprland) {
    return (hyprland.keybinds ?? []).filter((keybind) => keybind.enabled !== false);
}

// Lua's long-bracket string ([[ ... ]]) needs no escaping for quotes or
// backslashes, unlike a normal "..." literal — and a key or command the
// user types can contain either. It only breaks if the text itself
// contains "]]", which nothing here guards against.
function luaLongString(value) {
    return `[[${value}]]`;
}

// A keybind's command list (decision 7.5) becomes one `hl.dsp.exec_cmd`
// call, since a single `hl.bind` takes exactly one dispatcher — the
// commands are shell-joined with "; " so they run in order, one after
// another, as one dispatcher invocation.
function joinedCommand(keybind) {
    return (keybind.commands ?? []).join("; ");
}

export function generateKeybindsLua(hyprland) {
    const lines = [WARNING_BANNER, ""];

    for (const key of managedKeys(hyprland)) {
        lines.push(`hl.unbind(${luaLongString(key)})`);
    }
    lines.push("");

    for (const keybind of enabledKeybinds(hyprland)) {
        lines.push(`hl.bind(${luaLongString(keybind.key)}, hl.dsp.exec_cmd(${luaLongString(joinedCommand(keybind))}))`);
    }
    lines.push("");

    return lines.join("\n");
}
